import{_ as e,c as o,o as a,ae as l}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Custom Filters","description":"Custom Filters","frontmatter":{"title":"Custom Filters","description":"Custom Filters"},"headers":[],"relativePath":"guide/table-settings/custom-filters.md","filePath":"guide/table-settings/custom-filters.md"}'),i={name:"guide/table-settings/custom-filters.md"};function r(s,t,n,u,h,c){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="custom-filters" tabindex="-1">Custom Filters <a class="header-anchor" href="#custom-filters" aria-label="Permalink to &quot;Custom Filters&quot;">​</a></h1><p>Ninja Tables offers you a powerful feature known as <strong>Custom</strong> <strong>Filters</strong>, which lets you filter data from tables in various ways. Custom Filter is a Pro Feature!</p><ul><li>First, go to the <strong>Ninja Tables dashboard</strong> and select a your table to add filters.</li><li>Next, click the <strong>Table</strong> <strong>Configuration</strong> tab and pick <strong>Custom Filters</strong> from the left menubar. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-custom-filter-tab-1024x322.webp" alt="New Ui custom filter tab"></li></ul><h2 id="add-custom-filters" tabindex="-1">Add Custom Filters <a class="header-anchor" href="#add-custom-filters" aria-label="Permalink to &quot;Add Custom Filters&quot;">​</a></h2><ul><li>Click on the <strong>Custom</strong> <strong>Filters</strong>, there a new tab will open with an <strong>Add New Filter</strong> button.</li><li>Now, click the <strong>Add</strong> <strong>New</strong> <strong>Filter</strong> button, then a pop-up form with a set of configuration options will appear. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-add-custom-filter-1024x610.webp" alt="New Ui add custom filter"> This pop-up has various options to choose from to make your table’s filter more interactive. The following options can be found in the custom filter pop-up form -</li></ul><h3 id="filter-title" tabindex="-1"><strong>Filter Title</strong> <a class="header-anchor" href="#filter-title" aria-label="Permalink to &quot;**Filter Title**&quot;">​</a></h3><p>This input field is for the filter title, which determines the filter name.</p><h3 id="filter-label" tabindex="-1"><strong>Filter Label</strong> <a class="header-anchor" href="#filter-label" aria-label="Permalink to &quot;**Filter Label**&quot;">​</a></h3><p>This input field is used if you want to add a label to your filter. Keep it blank if you don’t need any filter instructions in the frontend.</p><h3 id="filter-ui-type" tabindex="-1"><strong>Filter UI Type</strong> <a class="header-anchor" href="#filter-ui-type" aria-label="Permalink to &quot;**Filter UI Type**&quot;">​</a></h3><p>You can choose the filter type to display the filter&#39;s base in the frontend. There are 8 subsets in the Filter UI type. Such as:</p><ul><li>Select Dropdown</li><li>Radio</li><li>Checkbox</li><li>Text Input</li><li>Date Picker</li><li>Date Range</li><li>Number Range</li><li>Reset Filter Button <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-custom-filter-ui-type-1024x574.webp" alt="New Ui custom filter ui type"></li></ul><h3 id="placeholder" tabindex="-1"><strong>Placeholder</strong> <a class="header-anchor" href="#placeholder" aria-label="Permalink to &quot;**Placeholder**&quot;">​</a></h3><p>The default placeholder is <strong>All</strong>. But if you want to change the text, you can type in your desired text.</p><h3 id="value-type" tabindex="-1"><strong>Value Type</strong> <a class="header-anchor" href="#value-type" aria-label="Permalink to &quot;**Value Type**&quot;">​</a></h3><p>Select How the value will be populated to the select dropdown. There are two types of Value types, including Manual Data and dynamic Data from the Table.</p><h4 id="manual-data" tabindex="-1"><strong>Manual Data</strong> <a class="header-anchor" href="#manual-data" aria-label="Permalink to &quot;**Manual Data**&quot;">​</a></h4><p>When you choose <strong>Manual</strong> <strong>Data</strong>, some options will appear below. <img src="https://ninjatables.com/wp-content/uploads/2023/01/custom-filters-5.png" alt="manual data in custom filter"></p><h5 id="filter-options" tabindex="-1"><strong>Filter Options</strong> <a class="header-anchor" href="#filter-options" aria-label="Permalink to &quot;**Filter Options**&quot;">​</a></h5><p>This lets you place the value through which the filter will be implemented. Put your desired values to display on the frontend, be aware that those values need to match your cell data on that table. Filter options feature three sequential fields called <strong>Label</strong>, <strong>Filter Value,</strong> and <strong>Action Button</strong>.</p><ul><li><strong>Label:</strong> The label of the filtered value is entered in the Label field.</li><li>**Filter Value: **Put the value you want filtered in the Filter Value field.</li><li><strong>Action Buttons:</strong> There are 2 action buttons to add (+) and delete (bin icon) in each of the Label and Filter Value fields.</li></ul><h5 id="dynamic-data-from-table-column" tabindex="-1"><strong>Dynamic Data from Table Column</strong> <a class="header-anchor" href="#dynamic-data-from-table-column" aria-label="Permalink to &quot;**Dynamic Data from Table Column**&quot;">​</a></h5><p>When choosing Dynamic Data from Value Type, more options will appear below.</p><ul><li>**Target Column: **This option enables you to select the column that you want to populate data. <img src="https://ninjatables.com/wp-content/uploads/2023/01/custom-filters-6.png" alt="dynamic data custom filter"></li><li><strong>Parse Comma Separated Words:</strong> If you enable this option, and you choose multiple value types, values will be shown with <strong>Comma</strong>.</li><li><strong>Disable automatic filter Value sorting:</strong> By default, value sorting is disabled. The value sorting option will also be <strong>activated</strong> if you select this option.</li><li>If Disable automatic filter value sorting is unchecked, then two more options will appear below, such as <strong>Sort Dynamic Value as &amp; Sort Algorithm</strong>.</li><li><strong>Sort Dynamic Value as:</strong> By this option, you can select either an <strong>Ascending</strong> order or <strong>Descending</strong> order.</li><li><strong>Sort Algorithm:</strong> You can sort the algorithm as a **text basis **or a <strong>Numeric basis</strong>.</li><li>**Enable Multi-Select: **Enable this select field if you want to choose the multi-select value type.</li><li>**Strict Mode: **Enable this mode if you want the results to be accurately matching the values.</li></ul><h3 id="filter-columns" tabindex="-1"><strong>Filter Columns</strong> <a class="header-anchor" href="#filter-columns" aria-label="Permalink to &quot;**Filter Columns**&quot;">​</a></h3><p>This option is to pick the columns you wish to apply the filter. You can choose any single column, or you can pick multiple columns.</p><h2 id="example-of-custom-filters" tabindex="-1">Example of Custom Filters <a class="header-anchor" href="#example-of-custom-filters" aria-label="Permalink to &quot;Example of Custom Filters&quot;">​</a></h2><p>Let&#39;s have a look at an example where you could better understand Custom Filters.</p><ul><li>If you have a table like this with a <strong>numeric</strong> <strong>column</strong> (data type must need to as Numeric Value) and you would like to include the option to filter by selecting the range, then you can quickly do it. <img src="https://ninjatables.com/wp-content/uploads/2023/01/custom-filters-7.png" alt="custom filter on numeric column"></li><li>You can add a new filter by selecting the Add New Filter button under Custom Filters. Next, enter a filter title, choose the filter UI type and value type, and provide the filter label and value in the filter options. Choose the Column to which you wish to apply the filter as well.</li><li>Here, For Greater than = <strong>{gt} yourValue</strong></li><li>For Less than = <strong>{lt} yourValue</strong></li><li>From firstValue to lastValue <strong>~firstValue: lastValue</strong></li><li>Don&#39;t forget to click on the <strong>Update</strong> button when you are done with your configuration. <img src="https://ninjatables.com/wp-content/uploads/2023/01/custom-filters-8.png" alt="select dropdown in custom filter"></li></ul><h3 id="filter-appearance" tabindex="-1"><strong>Filter Appearance</strong> <a class="header-anchor" href="#filter-appearance" aria-label="Permalink to &quot;**Filter Appearance**&quot;">​</a></h3><p>Once you&#39;ve set the filter, go to the main &quot;Custom Filter&quot; tab. You can choose any option in Filter Appearance between <strong>Show Filter inputs as Inlin</strong>e and <strong>Show Filter inputs as Columns</strong>. <img src="https://ninjatables.com/wp-content/uploads/2023/01/custom-filters-9.png" alt="custom filter appearance"></p><ul><li><strong>Show Filter inputs as Inline:</strong> It will show the filter inputs in a row.</li><li><strong>Show Filter inputs as Columns</strong>: The filter input area will be displayed as a column. See how Filter Appearance works in the table. <img src="https://ninjatables.com/wp-content/uploads/2023/01/custom-filters-10.png" alt="custom filter appearance"> Here&#39;s a WP Posts table created with Ninja Tables. It has custom filters enabled. The filter UI type is &quot;checkbox.&quot; You can select a checkbox and the corresponding filter will apply to the table. [ninja_tables id=&quot;4737&quot;]</li></ul><h2 id="progressive-filter" tabindex="-1"><strong>Progressive Filter</strong> <a class="header-anchor" href="#progressive-filter" aria-label="Permalink to &quot;**Progressive Filter**&quot;">​</a></h2><p>The user can filter any dynamic options in <strong>Progressive</strong> <strong>Filter</strong> to quickly access his specific requirements or desires. This option is enabled by default. Let’s see how this works! <a href="https://youtu.be/9pOi39RoFL4" target="_blank" rel="noreferrer">https://youtu.be/9pOi39RoFL4</a> This is how you can use <strong>Custom</strong> <strong>Filters</strong> in the table step by step!</p>',34)])])}const m=e(i,[["render",r]]);export{d as __pageData,m as default};
